//go:build ignore

// Command gen_operations lists the operations of an OpenAPI document, one "VERB /path" per line, for operations.txt.
//
//	go run testdata/gen_operations.go live-swagger.json > testdata/operations.txt
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"strings"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: go run testdata/gen_operations.go <openapi.json>")
		os.Exit(2)
	}
	data, err := os.ReadFile(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	var doc struct {
		Paths map[string]map[string]json.RawMessage `json:"paths"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	verbs := []string{"get", "put", "post", "delete", "options", "head", "patch", "trace"}
	var ops []string
	for path, item := range doc.Paths {
		for _, verb := range verbs {
			if _, ok := item[verb]; ok {
				ops = append(ops, strings.ToUpper(verb)+" "+path)
			}
		}
	}
	slices.Sort(ops)
	fmt.Println("# Generated by: go run testdata/gen_operations.go live-swagger.json > testdata/operations.txt")
	for _, op := range ops {
		fmt.Println(op)
	}
}
